import { CursorsRoot, CursorCanvas } from "@/components/bevelui/cursors";

export default function CollabPage() {
  return (
    <CursorsRoot
      localUser={{ userId: session.userId, userName: session.name }}
      onMove={(pos) => channel.send({ type: "cursor", ...pos })}
    >
      <CursorCanvas className="h-full w-full">
        <TransportWiring />
        {/* your shared content */}
      </CursorCanvas>
    </CursorsRoot>
  );
}

interface NormalizedPosition {
  x: number; // 0–1 fraction of container width
  y: number; // 0–1 fraction of container height
}

interface RemoteCursor {
  userId:   string;
  userName: string;
  position: NormalizedPosition;
}

interface LocalUser {
  userId:   string;
  userName: string;
  color?:   string; // override auto-assigned color
}

interface CursorMeta {
  userId:   string;
  userName: string;
  color:    string;
  isIdle:   boolean;
}
